package com.renthouse.operation;import com.renthouse.auth.*;import com.renthouse.common.api.*;import com.renthouse.common.exception.BusinessException;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/landlord/tenants")public class BlacklistController{private final JdbcTemplate j;public BlacklistController(JdbcTemplate j){this.j=j;}@PostMapping("/{tenantId}/blacklist")public ApiResponse<Void>block(@PathVariable long tenantId,@RequestBody @Valid Request r){CurrentUser.requireRole(UserRole.LANDLORD);Integer exists=j.queryForObject("SELECT COUNT(*) FROM tenancy_contract WHERE landlord_id=? AND tenant_id=?",Integer.class,CurrentUser.require().id(),tenantId);if(exists==null||exists==0)throw new BusinessException("TENANT_NOT_FOUND","该租客不属于当前房东",HttpStatus.NOT_FOUND);j.update("UPDATE sys_user SET status='BLACKLISTED',updated_at=? WHERE id=? AND role='TENANT'",LocalDateTime.now(),tenantId);j.update("UPDATE tenant_profile SET blacklist_reason=?,blacklist_at=?,updated_at=? WHERE user_id=?",r.reason(),LocalDateTime.now(),LocalDateTime.now(),tenantId);return ApiResponse.ok();}@DeleteMapping("/{tenantId}/blacklist")public ApiResponse<Void>unblock(@PathVariable long tenantId){CurrentUser.requireRole(UserRole.LANDLORD);j.update("UPDATE sys_user SET status='ACTIVE',updated_at=? WHERE id=? AND role='TENANT'",LocalDateTime.now(),tenantId);j.update("UPDATE tenant_profile SET blacklist_reason=NULL,blacklist_at=NULL,updated_at=? WHERE user_id=?",LocalDateTime.now(),tenantId);return ApiResponse.ok();}public record Request(@NotBlank@Size(max=255)String reason){}}
